-- Query session over one PQDIR (in the workbench: a run's parquets/).
-- Expects lib.sql loaded. bench-parquet replaces @PARQUETS@ by the quoted absolute
-- path of PQDIR: a literal, not a session variable, so the views also work
-- from other connections to the same database (e.g. the DuckDB UI, start_ui()).
-- Per-namespace views ("Forge.Loop.ForgedBlock", ...) are generated by bench-parquet
-- from the namespaces present in the run, after this file; then the package views
-- (views/1-events, 2-joined, 3-composed) and the checks (checks/) load, see README.md.

-- Raw layer: the nodes' stdout. The generator has its own view, raw_generator
-- (created by bench-parquet, empty when the run has none); combining the two is
-- explicit in a query, never the default.
CREATE OR REPLACE VIEW raw        AS SELECT * FROM read_parquet(@PARQUETS@ || '/node-*.parquet');

-- Metadata.
-- Columns added to meta/run.parquet later (epoch_length) read NULL in folders
-- converted before them.
CREATE OR REPLACE VIEW run_meta   AS
  SELECT * FROM (SELECT CAST(NULL AS BIGINT) AS epoch_length LIMIT 0)
  UNION ALL BY NAME
  SELECT * FROM read_parquet(@PARQUETS@ || '/meta/run.parquet');
CREATE OR REPLACE VIEW files      AS SELECT * FROM read_parquet(@PARQUETS@ || '/meta/files.parquet');

-- The run's genesis values. NULL in run_meta when the logs were converted
-- without them; then every use is an error, never a NULL slot or epoch. Columns
-- are qualified: a macro expanded inside another macro must not pick up that
-- macro's parameters of the same name.
CREATE OR REPLACE MACRO run_system_start() AS
  (SELECT coalesce(m.system_start, error('no genesis system start in meta/run.parquet (converted without --system-start)')) FROM run_meta m);
CREATE OR REPLACE MACRO run_slot_length_s() AS
  (SELECT coalesce(m.slot_length_s, error('no genesis slot length in meta/run.parquet (converted without --slot-length)')) FROM run_meta m);
CREATE OR REPLACE MACRO run_epoch_length() AS
  (SELECT coalesce(m.epoch_length, error('no genesis epoch length in meta/run.parquet (converted without --epoch-length)')) FROM run_meta m);

-- The instant slot s began, as genesis defines it (system_start + s * slot_length).
-- The genesis frame for views: no slot table needed to place a slot in time.
CREATE OR REPLACE MACRO slot_start(s) AS
  make_timestamp_ns(epoch_ns(run_system_start()) + CAST(s AS BIGINT) * CAST(run_slot_length_s() * 1e9 AS BIGINT));

-- A timestamp on the run's slot grid: the slot whose interval contains it. As
-- locli places Resources samples (impliedSlot); not a statement about which slot
-- a node was working on.
CREATE OR REPLACE MACRO slot_at(t) AS
  CAST(floor(  (epoch_ns(t) - epoch_ns(run_system_start()))
             / (run_slot_length_s() * 1e9)) AS BIGINT);

-- Severity, ordered as in trace-dispatcher's SeverityS. Stored as text; this type
-- only serves comparisons: sev_level(sev) >= 'Warning'. Strict: an unknown value
-- is an error.
CREATE TYPE severity AS ENUM ('Debug', 'Info', 'Notice', 'Warning', 'Error', 'Critical', 'Alert', 'Emergency');
CREATE OR REPLACE MACRO sev_level(s) AS CAST(s AS severity);

-- Fields that are stable in practice. Strict casts: a type change is an error,
-- never a NULL.
CREATE OR REPLACE MACRO slot_no(d)       AS CAST(d->>'$.slot'               AS UBIGINT);
CREATE OR REPLACE MACRO mempool_txs(d)   AS CAST(d->>'$.mempoolSize.numTxs' AS UBIGINT);
CREATE OR REPLACE MACRO mempool_bytes(d) AS CAST(d->>'$.mempoolSize.bytes'  AS UBIGINT);
-- Resources record fields:
CREATE OR REPLACE MACRO res_cpu(d)       AS CAST(d->>'$.CentiCpu' AS UBIGINT);  -- centiseconds, cumulative
CREATE OR REPLACE MACRO res_gc(d)        AS CAST(d->>'$.CentiGC'  AS UBIGINT);  -- centiseconds, cumulative
CREATE OR REPLACE MACRO res_mut(d)       AS CAST(d->>'$.CentiMut' AS UBIGINT);  -- centiseconds, cumulative
CREATE OR REPLACE MACRO res_rss(d)       AS CAST(d->>'$.RSS'      AS UBIGINT);  -- bytes
CREATE OR REPLACE MACRO res_heap(d)      AS CAST(d->>'$.Heap'     AS UBIGINT);  -- bytes
CREATE OR REPLACE MACRO res_live(d)      AS CAST(d->>'$.Live'     AS UBIGINT);  -- bytes
CREATE OR REPLACE MACRO res_alloc(d)     AS CAST(d->>'$.Alloc'    AS UBIGINT);  -- bytes, cumulative
CREATE OR REPLACE MACRO res_gcs_major(d) AS CAST(d->>'$.GcsMajor' AS UBIGINT);  -- count, cumulative
CREATE OR REPLACE MACRO res_gcs_minor(d) AS CAST(d->>'$.GcsMinor' AS UBIGINT);  -- count, cumulative
CREATE OR REPLACE MACRO res_threads(d)   AS CAST(d->>'$.Threads'  AS UBIGINT);
